import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Handler;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ReviewDemo {

    private static final Logger log = Logger.getLogger(ReviewDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger rootLogger = Logger.getLogger("");
        for (Handler handler : rootLogger.getHandlers()) {
            rootLogger.removeHandler(handler);
        }
        ConsoleHandler consoleHandler = new ConsoleHandler();
        consoleHandler.setFormatter(new BankLogFormatter());
        consoleHandler.setLevel(Level.ALL);
        rootLogger.addHandler(consoleHandler);
        rootLogger.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info(() -> "Starting code-review harmony demo at " + BANK_NAME);

        // Shared, agreed policy — the thing that ends the personal argument.
        MergeReadinessPolicy policy = new MergeReadinessPolicy(true, true);
        ReviewService reviewService = new ReviewService(policy);

        // Scenario 1: Rajesh's savings feature — touches money, has tests, has 2nd reviewer.
        ChangeRequest savingsChange = new ChangeRequest(
                "PR-5001", "Add standing instruction for SAV2001",
                true, true, true);

        // Scenario 2: Priya's report feature — touches money but missing tests + reviewer.
        ChangeRequest reportChange = new ChangeRequest(
                "PR-5002", "New current-account report for CUR3001",
                true, false, false);

        ReviewDecision d1 = reviewService.evaluate(savingsChange);
        ReviewDecision d2 = reviewService.evaluate(reportChange);

        log.info(() -> "Decision for " + savingsChange.getId() + ": " + d1.getSummary());
        log.info(() -> "Decision for " + reportChange.getId() + ": " + d2.getSummary());
    }
}

// ─── Would be in model/ChangeRequest.java in a real project ───
class ChangeRequest {
    private final String id;
    private final String description;
    private final boolean touchesMoney;
    private final boolean hasTests;
    private final boolean hasSecondReviewer;

    ChangeRequest(String id, String description, boolean touchesMoney,
                  boolean hasTests, boolean hasSecondReviewer) {
        this.id = id;
        this.description = description;
        this.touchesMoney = touchesMoney;
        this.hasTests = hasTests;
        this.hasSecondReviewer = hasSecondReviewer;
    }

    String getId() { return id; }
    String getDescription() { return description; }
    boolean touchesMoney() { return touchesMoney; }
    boolean hasTests() { return hasTests; }
    boolean hasSecondReviewer() { return hasSecondReviewer; }
}

// ─── Would be in model/ReviewDecision.java in a real project ───
class ReviewDecision {
    private final boolean approved;
    private final String summary;

    ReviewDecision(boolean approved, String summary) {
        this.approved = approved;
        this.summary = summary;
    }

    boolean isApproved() { return approved; }
    String getSummary() { return summary; }
}

// ─── Would be in policy/MergeReadinessPolicy.java in a real project ───
// The agreed rules that end the personal argument. Both engineers signed off on these once.
class MergeReadinessPolicy {
    private final boolean requireTestsForMoney;
    private final boolean requireSecondReviewerForMoney;

    MergeReadinessPolicy(boolean requireTestsForMoney, boolean requireSecondReviewerForMoney) {
        this.requireTestsForMoney = requireTestsForMoney;
        this.requireSecondReviewerForMoney = requireSecondReviewerForMoney;
    }

    ReviewDecision apply(ChangeRequest cr) {
        if (cr.touchesMoney()) {
            if (requireTestsForMoney && !cr.hasTests()) {
                return new ReviewDecision(false,
                        "BLOCKED — money-handling change needs tests. Add tests, not arguments.");
            }
            if (requireSecondReviewerForMoney && !cr.hasSecondReviewer()) {
                return new ReviewDecision(false,
                        "BLOCKED — money-handling change needs a second reviewer.");
            }
        }
        return new ReviewDecision(true, "APPROVED — meets the agreed definition of done.");
    }
}

// ─── Would be in service/ReviewService.java in a real project ───
class ReviewService {
    private static final Logger log = Logger.getLogger(ReviewService.class.getName());
    private final MergeReadinessPolicy policy;

    ReviewService(MergeReadinessPolicy policy) {
        this.policy = policy;
    }

    ReviewDecision evaluate(ChangeRequest cr) {
        log.fine(() -> "Evaluating " + cr.getId() + ": " + cr.getDescription());
        ReviewDecision decision = policy.apply(cr);
        if (decision.isApproved()) {
            log.info(() -> cr.getId() + " APPROVED objectively — no personal debate needed.");
        } else {
            log.warning(() -> cr.getId() + " needs work: " + decision.getSummary());
        }
        return decision;
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
                record.getMillis(),
                record.getLevel().getName(),
                record.getSourceClassName() != null
                        ? record.getSourceClassName().substring(
                                record.getSourceClassName().lastIndexOf('.') + 1)
                        : "Unknown",
                record.getMessage());
    }
}
